// /app/app/backdrop-dismiss.js — close an overlay on a click of its backdrop.
//
// A click is only a backdrop click when the press began on the backdrop too.
// On phones, focusing a field moves the dialog card (mobile-pager.css lifts it
// above the keyboard) between the press and the click, and Chrome hit-tests the
// click again: a tap on the amount field landed on the backdrop and closed the
// dialog. A drag ending outside a text selection is the desktop version.
// A click with no pointerdown before it (keyboard, element.click()) is judged
// on its target alone.

export function dismissOnBackdrop(backdrop, close) {
  if (!backdrop?.addEventListener) return;
  let pressTarget = null;
  backdrop.addEventListener('pointerdown', (event) => { pressTarget = event?.target ?? null; });
  backdrop.addEventListener('click', (event) => {
    const pressed = pressTarget;
    pressTarget = null;
    if (event?.target !== backdrop) return;
    if (pressed && pressed !== backdrop) return;
    close(event);
  });
}
